// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;

    function setUp() public {
        c = new Proxy();
    }

    function testFuzz_property(bool shouldFail, bytes memory data) public {
        Reverter r = new Reverter(shouldFail);
        bool ok = true;
        try c.forward(address(r), data) {
            ok = true;
        } catch {
            ok = false;
        }

        if (shouldFail) {
            assertTrue(!ok);
        } else {
            assertTrue(ok);
        }
    }
}

contract Reverter {
    bool private immutable fail;

    constructor(bool shouldFail) {
        fail = shouldFail;
    }

    fallback() external payable {
        if (fail) {
            revert();
        }
    }
}
